                String sdHashString;
                {
                    List<String> parts = new ArrayList<>();
                    parts.add(sdJwt.getIssuerSignedJWT().getJws());
                    parts.addAll(sdJwt.getDisclosures());
                    parts.add("");
                    sdHashString = String.join(OID4VCConstants.SDJWT_DELIMITER, parts);
